INSERT INTO public.hr_notifications(client_id,subject_id,id,reminder_key,kind,resource_id) SELECT c.client_id,%s,gen_random_uuid(),c.id::text || ':' || %s,'workflow_review',c.id FROM public.hr_cases c WHERE c.client_id=%s AND c.status='pending' AND c.updated_at<=%s AND public.hr_case_access(c.client_id,c.domain,'decide',c.employee_id) ON CONFLICT(client_id,subject_id,reminder_key) DO NOTHING;
